// Main.java
class UmurTidakValidException extends Exception {
    UmurTidakValidException(String pesan) {
        super(pesan);
    }
}

class Validator {
    static int cekUmur(int umur) throws UmurTidakValidException {
        if (umur < 0 || umur > ____) {
            throw new UmurTidakValidException("Umur tidak valid: " + umur);
        }
        return umur;
    }

    static int keAngka(String teks) {
        try {
            return Integer.parseInt(teks);
        } catch (____ e) {
            return -1;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        try {
            System.out.println("Umur sah: " + Validator.cekUmur(20));
            Validator.cekUmur(200);
        } catch (UmurTidakValidException e) {
            System.out.println(e.getMessage());
        }
        System.out.println("Angka: " + Validator.keAngka("abc"));
    }
}

